import{_ as e,H as r,f as a,i as n}from"./chunks/framework.Cg_xE-de.js";const i="/htmlOS-NEXT/docs/assets/proxy-hosts.Cakj7eSv.png",s="/htmlOS-NEXT/docs/assets/details-frontend.DbleyURV.png",o="/htmlOS-NEXT/docs/assets/ssl.DXPEjqrJ.png",l="/htmlOS-NEXT/docs/assets/details-backend.uVw7qP4p.png",S=JSON.parse('{"title":"Forwarding with Nginx Proxy Manager","description":"","frontmatter":{},"headers":[],"relativePath":"installation/forwarding-with-nginx-proxy-manager.md","filePath":"installation/forwarding-with-nginx-proxy-manager.md"}'),d={name:"installation/forwarding-with-nginx-proxy-manager.md"};function p(h,t,c,g,u,m){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="forwarding-with-nginx-proxy-manager" tabindex="-1">Forwarding with Nginx Proxy Manager <a class="header-anchor" href="#forwarding-with-nginx-proxy-manager" aria-label="Permalink to &quot;Forwarding with Nginx Proxy Manager&quot;">​</a></h1><p>If you want to forward htmlOS NEXT securely with a custom domain (e.g., <code>next.yourdomain.com</code>), you can route your traffic through <strong>Nginx Proxy Manager (NPM)</strong>.</p><p>This guide will walk you through configuring <strong>htmlOS NEXT</strong> to be forwarded by <strong>NPM</strong>.</p><h2 id="step-1-forward-the-frontend" tabindex="-1">Step 1: Forward the frontend <a class="header-anchor" href="#step-1-forward-the-frontend" aria-label="Permalink to &quot;Step 1: Forward the frontend&quot;">​</a></h2><p>Open your <strong>Nginx Proxy Manager</strong> interface and select <strong>Proxy Hosts</strong>.</p><p><img src="'+i+'" alt="&quot;Proxy Hosts&quot;"></p><p>Then click the <strong>Add Proxy Host</strong> button.</p><p>Then fill in the details:</p><ul><li>The domain name you wish to forward to</li><li>The hostname and port where the frontend is located</li><li>Block Common Exploits (optional)</li></ul><p><img src="'+s+'" alt="&quot;Frontend Details&quot;"></p><p>If you want HTTPS support, switch to the <strong>SSL</strong> tab, and:</p><ul><li>Select your SSL certificate</li><li>Enable <strong>Force SSL</strong></li><li>Enable <strong>HTTP/2 Support</strong></li></ul><p><img src="'+o+'" alt="&quot;SSL Tab&quot;"></p><p>Click the <strong>Save</strong> button.</p><h2 id="step-2-forward-the-backend" tabindex="-1">Step 2: Forward the backend <a class="header-anchor" href="#step-2-forward-the-backend" aria-label="Permalink to &quot;Step 2: Forward the backend&quot;">​</a></h2><p>Click the <strong>Add Proxy Host</strong> button.</p><p>Then fill in the details:</p><ul><li>The domain name you wish to forward to</li><li>The hostname and port where the backend is located</li><li>Block Common Exploits (optional)</li><li>Websockets Support (needed for the continuity feature)</li></ul><p><img src="'+l+'" alt="&quot;Backend Details&quot;"></p><p>If you want HTTPS support, switch to the <strong>SSL</strong> tab, and:</p><ul><li>Select your SSL certificate</li><li>Enable <strong>Force SSL</strong></li><li>Enable <strong>HTTP/2 Support</strong></li></ul><p><img src="'+o+'" alt="&quot;SSL Tab&quot;"></p><p>Click the <strong>Save</strong> button.</p><h2 id="step-3-update-the-environment-variables" tabindex="-1">Step 3: Update the environment variables <a class="header-anchor" href="#step-3-update-the-environment-variables" aria-label="Permalink to &quot;Step 3: Update the environment variables&quot;">​</a></h2><p>On your Docker Compose file, change these variables:</p><ul><li><code>FRONTEND_ADDRESSES</code>: To the domain you just gave the frontend.</li><li><code>VITE_BACKEND_ADDRESSES</code>: To the domain you just gave the backend.</li></ul><p>Then restart your Docker Compose stack.</p><p>After these changes, you should now be able to access your <strong>htmlOS NEXT</strong> instance from your domain.</p>',28)])])}const w=e(d,[["render",p]]);export{S as __pageData,w as default};
